def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        print("Cannot divide by zero")
        return None

print(safe_divide(10, 2))
print(safe_divide(10, 0))

values = ["12", "x", "7.5"]
for text in values:
    try:
        number = int(text)
    except ValueError as error:
        print(f"Skipping {text!r}: {error}")
    else:
        print("Parsed", number)

def total(record):
    try:
        return float(record["price"]) * int(record["quantity"])
    except KeyError as error:
        print("Missing field:", error)
    except (ValueError, TypeError) as error:
        print("Bad value:", error)
    return 0

print(total({"price": "19.99", "quantity": "two"}))
print(total({"price": "5"}))
print(total({"price": "5", "quantity": "3"}))

def read_config(path):
    print("Opening", path)
    try:
        if path.endswith(".yaml"):
            raise ValueError("YAML is not supported")
        return {"debug": True}
    finally:
        print("Closing", path)

print(read_config("settings.json"))
try:
    read_config("settings.yaml")
except ValueError as error:
    print("Error:", error)

class InsufficientFunds(Exception):
    """Raised when a withdrawal exceeds the balance."""

def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > balance:
        raise InsufficientFunds(f"balance {balance} is less than {amount}")
    return balance - amount

print(withdraw(100, 30))
for amount in (-5, 500):
    try:
        withdraw(100, amount)
    except InsufficientFunds as error:
        print("Declined:", error)
    except ValueError as error:
        print("Invalid:", error)

